&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;

&lt;table border=0 cellpadding=0 cellspacing=0 border=0 cellpadding=0 cellspacing=0&gt;&lt;tr&gt;&lt;td style="font-size: 15px; line-height: 1.48em; padding: 0px 18px;"&gt;

  &lt;p&gt;&lt;span style="font-weight: 400 !important; font-size: 1.3em !important; color: #000;"&gt;&lt;a href="https://frontendfoc.us/link/191247/rss" title="surveyjs.io" style=" color: #D94306;"&gt;Build Forms That Look Native in Your Frontend&lt;/a&gt;&lt;/span&gt; — Customize SurveyJS built-in themes or use adapters for Bootstrap, MUI, and shadcn/ui. Self-hosted, backend-agnostic, JSON-driven.&lt;/p&gt;
  &lt;p&gt;SurveyJS &lt;span style="text-transform: uppercase; margin-left: 4px; font-size: 0.9em;   color: #997 !important; padding: 1px 4px; "&gt;sponsor&lt;/span&gt;&lt;/p&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;

